def gen(rng):
    def build(n, mode):
        L = [-1] * n; R = [-1] * n
        if mode == 'rand':
            slots = [(0, 0), (0, 1)]
            for i in range(1, n):
                j = rng.randrange(len(slots))
                slots[j], slots[-1] = slots[-1], slots[j]
                x, side = slots.pop()
                if side == 0: L[x] = i
                else: R[x] = i
                slots.append((i, 0)); slots.append((i, 1))
        elif mode == 'complete':
            for i in range(n):
                if 2 * i + 1 < n: L[i] = 2 * i + 1
                if 2 * i + 2 < n: R[i] = 2 * i + 2
        elif mode == 'zigzag':
            for i in range(n - 1):
                if i % 2 == 0: L[i] = i + 1
                else: R[i] = i + 1
        elif mode == 'spine':
            spine = max(1, n // 2)
            for i in range(spine - 1):
                L[i] = i + 1
            for i in range(spine, n):
                while True:
                    x = rng.randrange(spine)
                    if R[x] == -1:
                        R[x] = i
                        break
        elif mode == 'sym':
            # random tree, then drop a few nodes of a complete tree
            keep = [True] * n
            for i in range(1, n):
                if rng.random() < 0.15:
                    keep[i] = False
            for i in range(n):
                for c, arr in ((2 * i + 1, L), (2 * i + 2, R)):
                    pass
            for i in range(n):
                if keep[i]:
                    if 2 * i + 1 < n and keep[2 * i + 1]: L[i] = 2 * i + 1
                    if 2 * i + 2 < n and keep[2 * i + 2]: R[i] = 2 * i + 2
        return L, R
    def serialize(L, R, vals):
        # only nodes reachable from the root appear
        out = [str(vals[0])]
        q = [0]
        qi = 0
        seen = [0]
        while qi < len(q):
            x = q[qi]; qi += 1
            for c in (L[x], R[x]):
                if c == -1:
                    out.append('null')
                else:
                    out.append(str(vals[c]))
                    q.append(c)
                    seen.append(c)
        while out[-1] == 'null':
            out.pop()
        return ' '.join(out), [vals[c] for c in seen]
    def make(n, mode, vmax=10**9):
        L, R = build(n, mode)
        vals = rng.sample(range(0, vmax + 1), n)
        s, present = serialize(L, R, vals)
        return s, present
    def fmt(s, present):
        u = rng.choice(present); v = rng.choice(present)
        return s + '\n' + f'{u} {v}'
    tests = ['5\n5 5', '1 2\n1 2', '1 2 3 4 null null 5\n4 5', '1 2 3 4 null null 5\n4 3', '1 2 null 3 null 4\n4 1',
             '7 null 3 null 9\n9 3', '10 20 30 40 50 60 70\n40 70', '10 20 30 40 50 60 70\n40 60', '3 1 2\n1 2']
    for n in (2, 3, 4, 6, 8, 10, 12):
        for mode in ('rand', 'complete', 'rand', 'sym', 'spine', 'zigzag'):
            if mode == 'spine' and n < 4:
                continue
            s, present = make(n, mode, 99)
            if len(s) < 300:
                tests.append(fmt(s, present))
        if len(tests) > 60:
            break
    for n, mode in ((100000, 'rand'), (65535, 'complete'), (5000, 'zigzag'), (10000, 'spine'), (100000, 'sym'), (3000, 'rand')):
        s, present = make(n, mode)
        tests.append(fmt(s, present))
    # far-apart pairs in the big trees
    s, present = make(65535, 'complete')
    tests.append(s + '\n' + f'{present[-1]} {present[len(present) // 2]}')
    s, present = make(5000, 'zigzag')
    tests.append(s + '\n' + f'{present[-1]} {present[0]}')
    return tests
